// Node "Formular vorbereiten": builds the fields of settings page 2 from the stored settings.
// - Dropdowns start on "<value in use> (aktuell)". The save step has no mapping for that option, so the stored value is kept.
// - Text, number and e-mail fields are filled with the value in use, so saving without a change writes the same value back.
// - Fields marked prefill: false stay empty and the placeholder says what is in use: the AI model and address (empty =
//   keep, or the new provider's default) and the multi-line fields (a browser would send their line breaks as CRLF).
//   Careful: an empty "Eigene Regeln" clears the company's rules; its placeholder says so.
// Labels stay as they are: the save step reads the answers by label.
const s = $('Einstellungen').first().json.data || {};
const KEEP = 'Unverändert lassen';
const shown = f => {
  const v = s[f.key];
  const t = v === undefined || v === null || v === '' ? '' : String((f.labels || {})[v] ?? v).replace(/\s*\n\s*/g, ' · ');
  return t || f.empty || 'nicht gesetzt';
};
const fields = [{"fieldLabel": "Abschnitt Antwortstil", "fieldType": "html", "html": "<h3>Antwortstil</h3><p>Wie die Antwort an den Kunden klingt.</p>"}, {"fieldLabel": "Sprache der Antwort", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "Sprache des Kunden übernehmen"}, {"option": "Immer Deutsch"}, {"option": "Immer Englisch (US)"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "language", "labels": {"auto": "Sprache des Kunden übernehmen", "de": "Immer Deutsch", "en-US": "Immer Englisch (US)"}}, {"fieldLabel": "Anrede", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "Sie"}, {"option": "du"}, {"option": "Wie der Kunde"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "formality", "labels": {"Sie": "Sie", "du": "du", "auto": "Wie der Kunde"}}, {"fieldLabel": "Ton", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "sachlich"}, {"option": "freundlich"}, {"option": "herzlich"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "tone", "labels": {}}, {"fieldLabel": "Länge", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "kurz"}, {"option": "normal"}, {"option": "ausführlich"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "length", "labels": {"short": "kurz", "normal": "normal", "detailed": "ausführlich"}}, {"fieldLabel": "Entschuldigung", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "Nur wenn wir schuld sind"}, {"option": "Immer"}, {"option": "Nie"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "apology", "labels": {"when_our_fault": "Nur wenn wir schuld sind", "always": "Immer", "never": "Nie"}}, {"fieldLabel": "Grußformel Deutsch", "key": "closing_de", "empty": "", "prefill": true}, {"fieldLabel": "Grußformel Englisch", "key": "closing_en", "empty": "", "prefill": true}, {"fieldLabel": "Signatur", "fieldType": "textarea", "key": "signature", "empty": "", "prefill": false}, {"fieldLabel": "Eigene Regeln", "fieldType": "textarea", "key": "custom_rules", "empty": "keine", "prefill": false, "hint": "leer = keine eigenen Regeln"}, {"fieldLabel": "Abschnitt Entscheidungen", "fieldType": "html", "html": "<h3>Entscheidungen</h3><p>Welche Lösung der Assistent vorschlägt. Die Regeln selbst stehen fest im Ablauf.</p>"}, {"fieldLabel": "Standardlösung bei Defekt", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "Ersatzlieferung"}, {"option": "Gutschrift"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "default_remedy", "labels": {"replacement": "Ersatzlieferung", "credit": "Gutschrift"}}, {"fieldLabel": "Gewährleistung Privatkunden (Monate)", "fieldType": "number", "key": "warranty_months_b2c", "empty": "", "prefill": true}, {"fieldLabel": "Gewährleistung Firmenkunden (Monate)", "fieldType": "number", "key": "warranty_months_b2b", "empty": "", "prefill": true}, {"fieldLabel": "Abschnitt KI", "fieldType": "html", "html": "<h3>KI</h3><p>Testmodell, Ollama und LM Studio laufen auf diesem Rechner: keine Daten gehen nach außen. Bei einem Cloud-Anbieter gehen der Text der Reklamation und die Rechnungsdaten an diesen Anbieter. API-Schlüssel stehen nicht in diesem Formular, sondern in der Datei .env.local auf dem Server. Modell und Adresse leer lassen: es bleibt der bisherige Wert, bei einem neuen Anbieter dessen Standard.</p>"}, {"fieldLabel": "KI-Anbieter", "fieldType": "dropdown", "fieldOptions": {"values": [{"option": "Unverändert lassen"}, {"option": "Testmodell (offline)"}, {"option": "Wie in Odoo eingerichtet"}, {"option": "Ollama (lokal)"}, {"option": "LM Studio (lokal)"}, {"option": "OpenAI"}, {"option": "Anthropic Claude"}, {"option": "Google Gemini"}, {"option": "Mistral"}, {"option": "Azure OpenAI"}, {"option": "Eigener Endpunkt"}]}, "requiredField": false, "defaultValue": "Unverändert lassen", "key": "llm_provider", "labels": {"mock": "Testmodell (offline)", "odoo": "Wie in Odoo eingerichtet", "ollama": "Ollama (lokal)", "lmstudio": "LM Studio (lokal)", "openai": "OpenAI", "anthropic": "Anthropic Claude", "gemini": "Google Gemini", "mistral": "Mistral", "azure": "Azure OpenAI", "custom": "Eigener Endpunkt"}}, {"fieldLabel": "KI-Modell", "key": "llm_model", "empty": "Standard", "prefill": false}, {"fieldLabel": "KI-Adresse (nur Azure, eigener Endpunkt oder entfernter Ollama)", "key": "llm_url", "empty": "keine", "prefill": false}, {"fieldLabel": "Abschnitt Freigabe", "fieldType": "html", "html": "<h3>Freigabe</h3><p>Wer die Freigabe-Mails bekommt.</p>"}, {"fieldLabel": "Freigabe an (E-Mail)", "fieldType": "email", "key": "approval_email", "empty": "", "prefill": true}].flatMap(f => {
  if (!f.key) return [f];
  const { key, labels, empty, prefill, hint, ...o } = f;
  const cur = shown(f);
  if (o.fieldType === 'dropdown') {
    const k = `${cur} (aktuell)`;
    const values = o.fieldOptions.values.filter(v => v.option !== cur).map(v => (v.option === KEEP ? { option: k } : v));
    return [{ ...o, fieldOptions: { values }, defaultValue: k }];
  }
  if (prefill === false) return [{ ...o, placeholder: `${hint || 'leer = wie bisher'} · jetzt: ${cur}` }];
  const v = s[key];
  return [{ ...o, defaultValue: v === undefined || v === null ? '' : v }];
});
return [{ json: { fields } }];

